/**
 * German names for the USDA food table.
 *
 * Generated by scripts/translate-usda-nutrition.ts (DeepL + a pinned canonical
 * vocabulary) and keyed by the English name rather than by fdcId, so it survives a
 * re-import of nutritionDb.ts — USDA fdcIds churn between releases, but the importer
 * itself merges on description.
 *
 * BLS entries are German-first and display as "German (English)". USDA is the mirror
 * image: the source data is English, so it displays as "English (German)".
 */
import namesDe from './nutritionNamesDe.json';
import { NUTRITION_DB } from './nutritionDb';

const NAMES_DE = namesDe as Record<string, string>;

/** German name for a USDA English name, or undefined if untranslated. */
export function usdaNameDe(name: string): string | undefined {
	return NAMES_DE[name];
}

/** Bilingual label: "English (German)", or just the English name if untranslated. */
export function usdaDisplayName(name: string): string {
	const de = NAMES_DE[name];
	return de ? `${name} (${de})` : name;
}

/** Both names for an fdcId, for detail views that render them on separate lines. */
export function usdaNamesFor(fdcId: number): { nameEn: string; nameDe?: string } | null {
	const entry = NUTRITION_DB.find((e) => e.fdcId === fdcId);
	if (!entry) return null;
	return { nameEn: entry.name, nameDe: NAMES_DE[entry.name] };
}
